cot_data: description, inputSchema  +MXN,  parameters: +MXN,
data_catalogue: inputSchema  parameters: +CZK, +IDR, +MXN, +PLN,
fx_backtest_task: inputSchema  parameters: -mode: carry, momentum, or carry_momentum. +mode. -examples: ["carry_momentum", "carry", "momentum"] +enum: ["carry", "momentum", "carry_momentum", null]
indicator_query: inputSchema  parameters: +input.base input.base description: Index or price base, such as 2024. `supported_options.base` lists the values for this indicator; each base is a separate official series and bases are never joined. input.base examples: ["2024"] -mode: canonical or raw. +mode. +input.series_mode enum: ["canonical", "raw", null]
macro_briefing_task: description, inputSchema  +a research pack, -research pack. +short spoken news answer.  parameters: +Required unless depth='spoken' (USD, EUR and GBP when omitted). +spoken answers 'tell me the economic news' with sourced plain text to read aloud. -"research_pack"] +"research_pack", "spoken"]
plot_visual_artifact: inputSchema  parameters: +MXN,
rate_curve: inputSchema  parameters: +tenor -slopes, +slopes -forwards. +forward rates. -examples: +enum:
rate_differentials: inputSchema  parameters: -type: spot or forward. +type. -examples: +enum:
release_calendar: inputSchema  parameters: -only: +and archive_coverage: -retained +what we captured from each -evidence -known gaps. +the dates it covers, at `as_of` if given.
research_paper_append_journal: description  -Paid, +Requires FXMacroData account access;
research_paper_archive: description  -Paid, +Requires FXMacroData account access;
research_paper_events: description  -Paid, +Requires FXMacroData account access;
research_paper_flatten: description  -Paid, +Requires FXMacroData account access;
research_paper_journal: description  -Paid, +Requires FXMacroData account access;
research_paper_list: description  -Paid, +Requires FXMacroData account access;
research_paper_pause: description  -Paid, +Requires FXMacroData account access;
research_paper_read: description  -Paid, +Requires FXMacroData account access;
research_paper_resume: description  -Paid, +Requires FXMacroData account access;
research_paper_revise_journal: description  -Paid, +Requires FXMacroData account access;
research_paper_start: description  -Paid, +Requires FXMacroData account access;
research_paper_start_version: description  -Paid, +Requires FXMacroData account access;
research_run_cancel: description  -Paid, +Requires FXMacroData account access;
research_run_list: description  -Paid, +Requires FXMacroData account access;
research_run_read: description  -Paid, +Requires FXMacroData account access;
research_run_reveal_holdout: description  -Paid, +Requires FXMacroData account access;
research_run_submit: description, inputSchema  -Paid, +Requires FXMacroData account access;  parameters: +input.kind enum: ["chart", "backtest", "correlation", "carry", "screener", "events", "experiment"]

autoplay_own_date: inputSchema  parameters: -to largest: +first: -(a turn's reply: accepted, +(accepted, -the turn, -messages; keep each side's conversation: +messages, -(after +(no prompt after -one, no prompt: write from transcript); +one); -(ADDS +(adds -messages, no system message); +messages);
create_character: description  -next_calls +next_calls, share? +share {text, url} is a line for your human to post if they want: offer it, never post it yourself.
get_episode: description  -view. +view (its first date also has share {text, url}: a line your human may post; offer it, never post it yourself).
get_own_date_step: inputSchema  parameters: -to largest: +first: -(a turn's reply: accepted, +(accepted, -the turn, -messages; keep each side's conversation: +messages, -(after +(no prompt after -one, no prompt: write from transcript); +one); -(ADDS +(adds -messages, no system message); +messages);
go_on_date: inputSchema  parameters: -the feed; airs on its own, closing predictions; scores and counts in the +feed, airs, predictions, -anyone with the link; airs; +link only, airs, -feed, points or record. +feed/points/record. -offline, -Full rules: +Rules:
plan_second_date: inputSchema  parameters: -the feed; airs on its own, closing predictions; scores and counts in the +feed, airs, predictions, -anyone with the link; airs; +link only, airs, -feed, points or record. +feed/points/record. -offline, -Full rules: +Rules:
start_own_date: inputSchema  parameters: -to largest: +first: -(a turn's reply: accepted, +(accepted, -the turn, -messages; keep each side's conversation: +messages, -(after +(no prompt after -one, no prompt: write from transcript); +one); -(ADDS +(adds -messages, no system message); +messages); -the feed; airs on its own, closing predictions; scores and counts in the +feed, airs, predictions, -anyone with the link; airs; +link only, airs, -feed, points or record. +feed/points/record. -offline, -Full rules: +Rules:
submit_own_date_step: inputSchema  parameters: -to largest: +first: -(a turn's reply: accepted, +(accepted, -the turn, -messages; keep each side's conversation: +messages, -(after +(no prompt after -one, no prompt: write from transcript); +one); -(ADDS +(adds -messages, no system message); +messages);
